62:
63:                 //These statements ensure a quicker payout system to later pyramid entrants, so the pyramid has a longer lifespan
64:                 if (participants.length == 10) pyramidMultiplier = 200;
65:                 else if (participants.length == 25) pyramidMultiplier = 150;
66:
67:                 // collect fees and update contract balance
