127:        uint208 balance; // current balance of user
128:    	uint16 lastDividendPeriod; // last processed dividend period of user's tokens
129:    	uint32 nextWithdrawBlock; // next withdrawal possible after this block number
130:    }
131:    mapping (address => Wallet) wallets;
132:    struct Bet {
133:        uint192 value; // bet size
134:        uint32 betHash; // selected numbers
135:        uint32 blockNum; // blocknumber when lottery runs
136:    }
137:    mapping (address => Bet) bets;
138:
139:    uint public walletBalance = 0; // sum of funds in wallets
140:
141:    // investment parameters
142:    uint public investStart = 1; // investment start block, 0: closed, 1: preparation
143:    uint public investBalance = 0; // funding from investors
144:    uint public investBalanceMax = 200000 ether; // maximum funding
145:    uint public dividendPeriod = 1;
146:    uint[] public dividends; // dividens collected per period, growing array
147:
148:    // betting parameters
149:    uint public maxWin = 0; // maximum prize won
150:    uint public hashFirst = 0; // start time of building hashes database
151:    uint public hashLast = 0; // last saved block of hashes
152:    uint public hashNext = 0; // next available bet block.number
153:    uint public hashBetSum = 0; // used bet volume of next block
154:    uint public hashBetMax = 5 ether; // maximum bet size per block
155:    uint[] public hashes; // space for storing lottery results
156:
157:    // constants
158:    //uint public constant hashesSize = 1024 ; // DEBUG ONLY !!!
159:    uint public constant hashesSize = 16384 ; // 30 days of blocks
160:    uint public coldStoreLast = 0 ; // block of last cold store transfer
161:
162:    // events
163:    event LogBet(address indexed player, uint bethash, uint blocknumber, uint betsize);
164:    event LogLoss(address indexed player, uint bethash, uint hash);
165:    event LogWin(address indexed player, uint bethash, uint hash, uint prize);
166:    event LogInvestment(address indexed investor, address indexed partner, uint amount);
167:    event LogRecordWin(address indexed player, uint amount);
168:    event LogLate(address indexed player,uint playerBlockNumber,uint currentBlockNumber);
169:    event LogDividend(address indexed investor, uint amount, uint period);
170:
171:    modifier onlyOwner() {
172:        assert(msg.sender == owner);
173:        _;
174:    }
175:
176:    modifier onlyAnimator() {
177:        assert(msg.sender == animator);
178:        _;
179:    }
180:
181:    // constructor
182:    function SmartBillions() {
183:        owner = msg.sender;
184:        animator = msg.sender;
185:        wallets[owner].lastDividendPeriod = uint16(dividendPeriod);
186:        dividends.push(0); // not used
187:        dividends.push(0); // current dividend
188:    }
189:
