191:
192:    /**
193:     * @dev Show length of allocated swap space
194:     */
195:    function hashesLength() constant external returns (uint) {
196:        return uint(hashes.length);
197:    }
198:
199:    /**
200:     * @dev Show balance of wallet
201:     * @param _owner The address of the account.
202:     */
203:    function walletBalanceOf(address _owner) constant external returns (uint) {
204:        return uint(wallets[_owner].balance);
205:    }
206:
