249:     */
250:    function dividendsBlocks() constant external returns (uint) {
251:        if(investStart > 0) {
252:            return(0);
253:        }
254:        uint period = (block.number - hashFirst) / (10 * hashesSize);
255:        if(period > dividendPeriod) {
256:            return(0);
