310:    /**
311:     * @dev Move funds to cold storage
312:     * @dev investBalance and walletBalance is protected from withdraw by owner
313:     * @dev if funding is > 50% admin can withdraw only 0.25% of balance weakly
314:     * @param _amount The amount of wei to move to cold storage
315:     */
316:    function coldStore(uint _amount) external onlyOwner {
317:        houseKeeping();
318:        require(_amount > 0 && this.balance >= (investBalance * 9 / 10) + walletBalance + _amount);
319:        if(investBalance >= investBalanceMax / 2){ // additional jackpot protection
320:            require((_amount <= this.balance / 400) && coldStoreLast + 4 * 60 * 24 * 7 <= block.number);
321:        }
322:        msg.sender.transfer(_amount);
323:        coldStoreLast = block.number;
