335:    /**
336:     * @dev Update accounting
337:     */
338:    function houseKeeping() public {
339:        if(investStart > 1 && block.number >= investStart + (hashesSize * 5)){ // ca. 14 days
340:            investStart = 0; // start dividend payments
341:        }
342:        else {
343:            if(hashFirst > 0){
344:		        uint period = (block.number - hashFirst) / (10 * hashesSize );
345:                if(period > dividends.length - 2) {
346:                    dividends.push(0);
347:                }
348:                if(period > dividendPeriod && investStart == 0 && dividendPeriod < dividends.length - 1) {
349:                    dividendPeriod++;
350:                }
351:            }
352:        }
