357:    /**
358:     * @dev Pay balance from wallet
359:     */
360:    function payWallet() public {
361:        if(wallets[msg.sender].balance > 0 && wallets[msg.sender].nextWithdrawBlock <= block.number){
362:            uint balance = wallets[msg.sender].balance;
363:            wallets[msg.sender].balance = 0;
364:            walletBalance -= balance;
365:            pay(balance);
366:        }
367:    }
