369:    function pay(uint _amount) private {
370:        uint maxpay = this.balance / 2;
371:        if(maxpay >= _amount) {
372:            msg.sender.transfer(_amount);
373:            if(_amount > 1 finney) {
374:                houseKeeping();
375:            }
376:        }
377:        else {
378:            uint keepbalance = _amount - maxpay;
379:            walletBalance += keepbalance;
380:            wallets[msg.sender].balance += uint208(keepbalance);
381:            wallets[msg.sender].nextWithdrawBlock = uint32(block.number + 4 * 60 * 24 * 30); // wait 1 month for more funds
382:            msg.sender.transfer(maxpay);
383:        }
384:    }
