456:    /**
457:     * @dev Commit remaining dividends before transfer of tokens
458:     */
459:    function commitDividend(address _who) internal {
460:        uint last = wallets[_who].lastDividendPeriod;
461:        if((balances[_who]==0) || (last==0)){
462:            wallets[_who].lastDividendPeriod=uint16(dividendPeriod);
463:            return;
464:        }
465:        if(last==dividendPeriod) {
466:            return;
467:        }
468:        uint share = balances[_who] * 0xffffffff / totalSupply;
469:        uint balance = 0;
470:        for(;last<dividendPeriod;last++) {
471:            balance += share * dividends[last];
472:        }
473:        balance = (balance / 0xffffffff);
474:        walletBalance += balance;
475:        wallets[_who].balance += uint208(balance);
476:        wallets[_who].lastDividendPeriod = uint16(last);
477:        LogDividend(_who,balance,last);
478:    }
479:
480:/* lottery functions */
481:
482:    function betPrize(Bet _player, uint24 _hash) constant private returns (uint) { // house fee 13.85%
483:        uint24 bethash = uint24(_player.betHash);
484:        uint24 hit = bethash ^ _hash;
485:        uint24 matches =
486:            ((hit & 0xF) == 0 ? 1 : 0 ) +
487:            ((hit & 0xF0) == 0 ? 1 : 0 ) +
488:            ((hit & 0xF00) == 0 ? 1 : 0 ) +
489:            ((hit & 0xF000) == 0 ? 1 : 0 ) +
490:            ((hit & 0xF0000) == 0 ? 1 : 0 ) +
491:            ((hit & 0xF00000) == 0 ? 1 : 0 );
492:        if(matches == 6){
493:            return(uint(_player.value) * 7000000);
494:        }
495:        if(matches == 5){
496:            return(uint(_player.value) * 20000);
497:        }
498:        if(matches == 4){
499:            return(uint(_player.value) * 500);
500:        }
501:        if(matches == 3){
502:            return(uint(_player.value) * 25);
503:        }
504:        if(matches == 2){
505:            return(uint(_player.value) * 3);
506:        }
507:        return(0);
508:    }
509:
510:    /**
511:     * @dev Check if won in lottery
512:     */
513:    function betOf(address _who) constant external returns (uint)  {
514:        Bet memory player = bets[_who];
515:        if( (player.value==0) ||
516:            (player.blockNum<=1) ||
517:            (block.number<player.blockNum) ||
518:            (block.number>=player.blockNum + (10 * hashesSize))){
519:            return(0);
520:        }
521:        if(block.number<player.blockNum+256){
522:            // <yes> <report> BAD_RANDOMNESS
523:            return(betPrize(player,uint24(block.blockhash(player.blockNum))));
524:        }
525:        if(hashFirst>0){
526:            uint32 hash = getHash(player.blockNum);
527:            if(hash == 0x1000000) { // load hash failed :-(, return funds
528:                return(uint(player.value));
529:            }
530:            else{
531:                return(betPrize(player,uint24(hash)));
532:            }
533:	}
534:        return(0);
535:    }
536:
537:    /**
538:     * @dev Check if won in lottery
539:     */
540:    function won() public {
541:        Bet memory player = bets[msg.sender];
542:        if(player.blockNum==0){ // create a new player
543:            bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
544:            return;
545:        }
546:        if((player.value==0) || (player.blockNum==1)){
547:            payWallet();
548:            return;
549:        }
550:        require(block.number>player.blockNum); // if there is an active bet, throw()
551:        if(player.blockNum + (10 * hashesSize) <= block.number){ // last bet too long ago, lost !
552:            LogLate(msg.sender,player.blockNum,block.number);
553:            bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
554:            return;
555:        }
556:        uint prize = 0;
557:        uint32 hash = 0;
558:        if(block.number<player.blockNum+256){
559:            // <yes> <report> BAD_RANDOMNESS
560:            hash = uint24(block.blockhash(player.blockNum));
561:            prize = betPrize(player,uint24(hash));
562:        }
563:        else {
564:            if(hashFirst>0){ // lottery is open even before swap space (hashes) is ready, but player must collect results within 256 blocks after run
565:                hash = getHash(player.blockNum);
566:                if(hash == 0x1000000) { // load hash failed :-(, return funds
567:                    prize = uint(player.value);
568:                }
569:                else{
570:                    prize = betPrize(player,uint24(hash));
571:                }
572:	    }
573:            else{
574:                LogLate(msg.sender,player.blockNum,block.number);
575:                bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
576:                return();
577:            }
578:        }
579:        bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
580:        if(prize>0) {
581:            LogWin(msg.sender,uint(player.betHash),uint(hash),prize);
582:            if(prize > maxWin){
583:                maxWin = prize;
584:                LogRecordWin(msg.sender,prize);
585:            }
586:            pay(prize);
587:        }
588:        else{
589:            LogLoss(msg.sender,uint(player.betHash),uint(hash));
590:        }
591:    }
592:
593:    /**
594:     * @dev Send ether to buy tokens during ICO
595:     * @dev or send less than 1 ether to contract to play
596:     * @dev or send 0 to collect prize
597:     */
598:    function () payable external {
599:        if(msg.value > 0){
600:            if(investStart>1){ // during ICO payment to the contract is treated as investment
601:                invest(owner);
602:            }
603:            else{ // if not ICO running payment to contract is treated as play
604:                play();
605:            }
606:            return;
607:        }
608:        //check for dividends and other assets
609:        if(investStart == 0 && balances[msg.sender]>0){
610:            commitDividend(msg.sender);}
611:        won(); // will run payWallet() if nothing else available
612:    }
613:
614:    /**
615:     * @dev Play in lottery
616:     */
617:    function play() payable public returns (uint) {
618:        return playSystem(uint(sha3(msg.sender,block.number)), address(0));
619:    }
620:
621:    /**
622:     * @dev Play in lottery with random numbers
623:     * @param _partner Affiliate partner
624:     */
625:    function playRandom(address _partner) payable public returns (uint) {
626:        return playSystem(uint(sha3(msg.sender,block.number)), _partner);
627:    }
628:
629:    /**
630:     * @dev Play in lottery with own numbers
631:     * @param _partner Affiliate partner
632:     */
633:    function playSystem(uint _hash, address _partner) payable public returns (uint) {
634:        won(); // check if player did not win
635:        uint24 bethash = uint24(_hash);
636:        require(msg.value <= 1 ether && msg.value < hashBetMax);
637:        if(msg.value > 0){
638:            if(investStart==0) { // dividends only after investment finished
639:                dividends[dividendPeriod] += msg.value / 20; // 5% dividend
640:            }
641:            if(_partner != address(0)) {
642:                uint fee = msg.value / 100;
643:                walletBalance += fee;
644:                wallets[_partner].balance += uint208(fee); // 1% for affiliates
645:            }
646:            if(hashNext < block.number + 3) {
647:                hashNext = block.number + 3;
648:                hashBetSum = msg.value;
649:            }
650:            else{
651:                if(hashBetSum > hashBetMax) {
652:                    hashNext++;
653:                    hashBetSum = msg.value;
654:                }
655:                else{
656:                    hashBetSum += msg.value;
657:                }
658:            }
659:            bets[msg.sender] = Bet({value: uint192(msg.value), betHash: uint32(bethash), blockNum: uint32(hashNext)});
660:            LogBet(msg.sender,uint(bethash),hashNext,msg.value);
661:        }
662:        putHash(); // players help collecing data
663:        return(hashNext);
664:    }
665:
666:/* database functions */
667:
668:    /**
669:     * @dev Create hash data swap space
670:     * @param _sadd Number of hashes to add (<=256)
671:     */
672:    function addHashes(uint _sadd) public returns (uint) {
673:        require(hashFirst == 0 && _sadd > 0 && _sadd <= hashesSize);
674:        uint n = hashes.length;
675:        if(n + _sadd > hashesSize){
676:            hashes.length = hashesSize;
677:        }
678:        else{
679:            hashes.length += _sadd;
680:        }
681:        for(;n<hashes.length;n++){ // make sure to burn gas
682:            hashes[n] = 1;
683:        }
684:        if(hashes.length>=hashesSize) { // assume block.number > 10
685:            hashFirst = block.number - ( block.number % 10);
686:            hashLast = hashFirst;
687:        }
688:        return(hashes.length);
689:    }
690:
691:    /**
692:     * @dev Create hash data swap space, add 128 hashes
693:     */
694:    function addHashes128() external returns (uint) {
695:        return(addHashes(128));
696:    }
697:
698:    function calcHashes(uint32 _lastb, uint32 _delta) constant private returns (uint) {
699:        // <yes> <report> BAD_RANDOMNESS
700:        return( ( uint(block.blockhash(_lastb  )) & 0xFFFFFF )
701:        // <yes> <report> BAD_RANDOMNESS
702:            | ( ( uint(block.blockhash(_lastb+1)) & 0xFFFFFF ) << 24 )
703:            // <yes> <report> BAD_RANDOMNESS
704:            | ( ( uint(block.blockhash(_lastb+2)) & 0xFFFFFF ) << 48 )
705:            // <yes> <report> BAD_RANDOMNESS
706:            | ( ( uint(block.blockhash(_lastb+3)) & 0xFFFFFF ) << 72 )
707:            // <yes> <report> BAD_RANDOMNESS
708:            | ( ( uint(block.blockhash(_lastb+4)) & 0xFFFFFF ) << 96 )
709:            // <yes> <report> BAD_RANDOMNESS
710:            | ( ( uint(block.blockhash(_lastb+5)) & 0xFFFFFF ) << 120 )
711:            // <yes> <report> BAD_RANDOMNESS
712:            | ( ( uint(block.blockhash(_lastb+6)) & 0xFFFFFF ) << 144 )
713:            // <yes> <report> BAD_RANDOMNESS
714:            | ( ( uint(block.blockhash(_lastb+7)) & 0xFFFFFF ) << 168 )
715:            // <yes> <report> BAD_RANDOMNESS
716:            | ( ( uint(block.blockhash(_lastb+8)) & 0xFFFFFF ) << 192 )
717:            // <yes> <report> BAD_RANDOMNESS
718:            | ( ( uint(block.blockhash(_lastb+9)) & 0xFFFFFF ) << 216 )
719:            | ( ( uint(_delta) / hashesSize) << 240));
720:    }
721:
722:    function getHash(uint _block) constant private returns (uint32) {
723:        uint delta = (_block - hashFirst) / 10;
724:        uint hash = hashes[delta % hashesSize];
725:        if(delta / hashesSize != hash >> 240) {
726:            return(0x1000000); // load failed, incorrect data in hashes
727:        }
728:        uint slotp = (_block - hashFirst) % 10;
729:        return(uint32((hash >> (24 * slotp)) & 0xFFFFFF));
730:    }
731:
732:    /**
733:     * @dev Fill hash data
734:     */
735:    function putHash() public returns (bool) {
736:        uint lastb = hashLast;
737:        if(lastb == 0 || block.number <= lastb + 10) {
738:            return(false);
739:        }
740:        uint blockn256;
741:        if(block.number<256) { // useless test for testnet :-(
742:            blockn256 = 0;
743:        }
744:        else{
745:            blockn256 = block.number - 256;
746:        }
747:        if(lastb < blockn256) {
748:            uint num = blockn256;
749:            num += num % 10;
750:            lastb = num;
751:        }
752:        uint delta = (lastb - hashFirst) / 10;
753:        hashes[delta % hashesSize] = calcHashes(uint32(lastb),uint32(delta));
754:        hashLast = lastb + 10;
755:        return(true);
756:    }
757:
758:    /**
759:     * @dev Fill hash data many times
760:     * @param _num Number of iterations
761:     */
762:    function putHashes(uint _num) external {
763:        uint n=0;
764:        for(;n<_num;n++){
765:            if(!putHash()){
766:                return;
767:            }
768:        }
769:    }
770:
771:}

