399:    function invest(address _partner) payable public {
400:        //require(fromUSA()==false); // fromUSA() not yet implemented :-(
401:        require(investStart > 1 && block.number < investStart + (hashesSize * 5) && investBalance < investBalanceMax);
402:        uint investing = msg.value;
403:        if(investing > investBalanceMax - investBalance) {
404:            investing = investBalanceMax - investBalance;
405:            investBalance = investBalanceMax;
406:            investStart = 0; // close investment round
407:            msg.sender.transfer(msg.value.sub(investing)); // send back funds immediately
408:        }
409:        else{
410:            investBalance += investing;
411:        }
412:        if(_partner == address(0) || _partner == owner){
413:            walletBalance += investing / 10;
414:            wallets[owner].balance += uint208(investing / 10);} // 10% for marketing if no affiliates
415:        else{
416:            walletBalance += (investing * 5 / 100) * 2;
417:            wallets[owner].balance += uint208(investing * 5 / 100); // 5% initial marketing funds
418:            wallets[_partner].balance += uint208(investing * 5 / 100);} // 5% for affiliates
419:        wallets[msg.sender].lastDividendPeriod = uint16(dividendPeriod); // assert(dividendPeriod == 1);
420:        uint senderBalance = investing / 10**15;
421:        uint ownerBalance = investing * 16 / 10**17  ;
422:        uint animatorBalance = investing * 10 / 10**17  ;
423:        balances[msg.sender] += senderBalance;
424:        balances[owner] += ownerBalance ; // 13% of shares go to developers
425:        balances[animator] += animatorBalance ; // 8% of shares go to animator
426:        totalSupply += senderBalance + ownerBalance + animatorBalance;
427:        Transfer(address(0),msg.sender,senderBalance); // for etherscan
428:        Transfer(address(0),owner,ownerBalance); // for etherscan
429:        Transfer(address(0),animator,animatorBalance); // for etherscan
430:        LogInvestment(msg.sender,_partner,investing);
