437:        require(investStart == 0);
438:        commitDividend(msg.sender);
439:        uint initialInvestment = balances[msg.sender] * 10**15;
440:        Transfer(msg.sender,address(0),balances[msg.sender]); // for etherscan
441:        delete balances[msg.sender]; // totalSupply stays the same, investBalance is reduced
442:        investBalance -= initialInvestment;
443:        wallets[msg.sender].balance += uint208(initialInvestment * 9 / 10);
444:        payWallet();
