459:    function commitDividend(address _who) internal {
460:        uint last = wallets[_who].lastDividendPeriod;
461:        if((balances[_who]==0) || (last==0)){
462:            wallets[_who].lastDividendPeriod=uint16(dividendPeriod);
463:            return;
464:        }
465:        if(last==dividendPeriod) {
466:            return;
467:        }
468:        uint share = balances[_who] * 0xffffffff / totalSupply;
469:        uint balance = 0;
470:        for(;last<dividendPeriod;last++) {
471:            balance += share * dividends[last];
472:        }
473:        balance = (balance / 0xffffffff);
474:        walletBalance += balance;
475:        wallets[_who].balance += uint208(balance);
476:        wallets[_who].lastDividendPeriod = uint16(last);
477:        LogDividend(_who,balance,last);
478:    }
