537:    /**
538:     * @dev Check if won in lottery
539:     */
540:    function won() public {
541:        Bet memory player = bets[msg.sender];
542:        if(player.blockNum==0){ // create a new player
543:            bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
544:            return;
545:        }
546:        if((player.value==0) || (player.blockNum==1)){
547:            payWallet();
548:            return;
549:        }
550:        require(block.number>player.blockNum); // if there is an active bet, throw()
551:        if(player.blockNum + (10 * hashesSize) <= block.number){ // last bet too long ago, lost !
552:            LogLate(msg.sender,player.blockNum,block.number);
553:            bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
554:            return;
555:        }
556:        uint prize = 0;
557:        uint32 hash = 0;
558:        if(block.number<player.blockNum+256){
559:            // <yes> <report> BAD_RANDOMNESS
560:            hash = uint24(block.blockhash(player.blockNum));
561:            prize = betPrize(player,uint24(hash));
562:        }
563:        else {
564:            if(hashFirst>0){ // lottery is open even before swap space (hashes) is ready, but player must collect results within 256 blocks after run
565:                hash = getHash(player.blockNum);
566:                if(hash == 0x1000000) { // load hash failed :-(, return funds
567:                    prize = uint(player.value);
568:                }
569:                else{
570:                    prize = betPrize(player,uint24(hash));
571:                }
572:	    }
573:            else{
574:                LogLate(msg.sender,player.blockNum,block.number);
575:                bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
576:                return();
577:            }
578:        }
579:        bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});
580:        if(prize>0) {
581:            LogWin(msg.sender,uint(player.betHash),uint(hash),prize);
582:            if(prize > maxWin){
583:                maxWin = prize;
584:                LogRecordWin(msg.sender,prize);
585:            }
586:            pay(prize);
587:        }
588:        else{
589:            LogLoss(msg.sender,uint(player.betHash),uint(hash));
590:        }
591:    }
