482:    function betPrize(Bet _player, uint24 _hash) constant private returns (uint) { // house fee 13.85%
483:        uint24 bethash = uint24(_player.betHash);
484:        uint24 hit = bethash ^ _hash;
485:        uint24 matches =
486:            ((hit & 0xF) == 0 ? 1 : 0 ) +
487:            ((hit & 0xF0) == 0 ? 1 : 0 ) +
488:            ((hit & 0xF00) == 0 ? 1 : 0 ) +
489:            ((hit & 0xF000) == 0 ? 1 : 0 ) +
490:            ((hit & 0xF0000) == 0 ? 1 : 0 ) +
491:            ((hit & 0xF00000) == 0 ? 1 : 0 );
492:        if(matches == 6){
493:            return(uint(_player.value) * 7000000);
494:        }
495:        if(matches == 5){
496:            return(uint(_player.value) * 20000);
497:        }
498:        if(matches == 4){
499:            return(uint(_player.value) * 500);
500:        }
501:        if(matches == 3){
502:            return(uint(_player.value) * 25);
503:        }
504:        if(matches == 2){
505:            return(uint(_player.value) * 3);
506:        }
507:        return(0);
508:    }
