562:        }
563:        else {
564:            if(hashFirst>0){ // lottery is open even before swap space (hashes) is ready, but player must collect results within 256 blocks after run
565:                hash = getHash(player.blockNum);
566:                if(hash == 0x1000000) { // load hash failed :-(, return funds
