698:    function calcHashes(uint32 _lastb, uint32 _delta) constant private returns (uint) {
699:        // <yes> <report> BAD_RANDOMNESS
700:        return( ( uint(block.blockhash(_lastb  )) & 0xFFFFFF )
701:        // <yes> <report> BAD_RANDOMNESS
702:            | ( ( uint(block.blockhash(_lastb+1)) & 0xFFFFFF ) << 24 )
703:            // <yes> <report> BAD_RANDOMNESS
704:            | ( ( uint(block.blockhash(_lastb+2)) & 0xFFFFFF ) << 48 )
705:            // <yes> <report> BAD_RANDOMNESS
706:            | ( ( uint(block.blockhash(_lastb+3)) & 0xFFFFFF ) << 72 )
707:            // <yes> <report> BAD_RANDOMNESS
708:            | ( ( uint(block.blockhash(_lastb+4)) & 0xFFFFFF ) << 96 )
709:            // <yes> <report> BAD_RANDOMNESS
710:            | ( ( uint(block.blockhash(_lastb+5)) & 0xFFFFFF ) << 120 )
711:            // <yes> <report> BAD_RANDOMNESS
712:            | ( ( uint(block.blockhash(_lastb+6)) & 0xFFFFFF ) << 144 )
713:            // <yes> <report> BAD_RANDOMNESS
714:            | ( ( uint(block.blockhash(_lastb+7)) & 0xFFFFFF ) << 168 )
715:            // <yes> <report> BAD_RANDOMNESS
716:            | ( ( uint(block.blockhash(_lastb+8)) & 0xFFFFFF ) << 192 )
717:            // <yes> <report> BAD_RANDOMNESS
718:            | ( ( uint(block.blockhash(_lastb+9)) & 0xFFFFFF ) << 216 )
719:            | ( ( uint(_delta) / hashesSize) << 240));
720:    }
