732:    /**
733:     * @dev Fill hash data
734:     */
735:    function putHash() public returns (bool) {
736:        uint lastb = hashLast;
737:        if(lastb == 0 || block.number <= lastb + 10) {
738:            return(false);
739:        }
740:        uint blockn256;
741:        if(block.number<256) { // useless test for testnet :-(
742:            blockn256 = 0;
743:        }
744:        else{
745:            blockn256 = block.number - 256;
746:        }
747:        if(lastb < blockn256) {
748:            uint num = blockn256;
749:            num += num % 10;
750:            lastb = num;
751:        }
752:        uint delta = (lastb - hashFirst) / 10;
753:        hashes[delta % hashesSize] = calcHashes(uint32(lastb),uint32(delta));
754:        hashLast = lastb + 10;
755:        return(true);
756:    }
