1459:/// @title Clock auction for non-fungible tokens.
1460:/// @notice We omit a fallback function to prevent accidental sends to this contract.
1461:contract ClockAuction is Pausable, ClockAuctionBase {
1462:
1463:    /// @dev The ERC-165 interface signature for ERC-721.
1464:    ///  Ref: https://github.com/ethereum/EIPs/issues/165
1465:    ///  Ref: https://github.com/ethereum/EIPs/issues/721
1466:    bytes4 constant InterfaceSignature_ERC721 = bytes4(0x9a20483d);
1467:
1468:    /// @dev Constructor creates a reference to the NFT ownership contract
1469:    ///  and verifies the owner cut is in the valid range.
1470:    /// @param _nftAddress - address of a deployed contract implementing
1471:    ///  the Nonfungible Interface.
1472:    /// @param _cut - percent cut the owner takes on each auction, must be
1473:    ///  between 0-10,000.
1474:    function ClockAuction(address _nftAddress, uint256 _cut) public {
1475:        require(_cut <= 10000);
1476:        ownerCut = _cut;
1477:
1478:        ERC721 candidateContract = ERC721(_nftAddress);
1479:        require(candidateContract.supportsInterface(InterfaceSignature_ERC721));
1480:        nonFungibleContract = candidateContract;
1481:    }
1482:
1483:    /// @dev Remove all Ether from the contract, which is the owner's cuts
1484:    ///  as well as any Ether sent directly to the contract address.
1485:    ///  Always transfers to the NFT contract, but can be called either by
1486:    ///  the owner or the NFT contract.
1487:    function withdrawBalance() external {
1488:        address nftAddress = address(nonFungibleContract);
1489:
1490:        require(
1491:            msg.sender == owner ||
1492:            msg.sender == nftAddress
1493:        );
1494:        // We are using this boolean method to make sure that even if one fails it will still work
1495:        // <yes> <report> UNCHECKED_LL_CALLS
1496:        bool res = nftAddress.send(this.balance);
1497:    }
