1689:contract SaleClockAuction is ClockAuction {
1690:
1691:    // @dev Sanity check that allows us to ensure that we are pointing to the
1692:    //  right auction in our setSaleAuctionAddress() call.
1693:    bool public isSaleClockAuction = true;
