1698:    uint256 public constant SurpriseValue = 10 finney;
1699:
1700:    uint256[] CommonPanda;
1701:    uint256[] RarePanda;
1702:    uint256   CommonPandaIndex;
1703:    uint256   RarePandaIndex;
1704:
1705:    // Delegate constructor
1706:    function SaleClockAuction(address _nftAddr, uint256 _cut) public
1707:        ClockAuction(_nftAddr, _cut) {
1708:            CommonPandaIndex = 1;
1709:            RarePandaIndex   = 1;
1710:    }
1711:
1712:    /// @dev Creates and begins a new auction.
1713:    /// @param _tokenId - ID of token to auction, sender must be owner.
1714:    /// @param _startingPrice - Price of item (in wei) at beginning of auction.
1715:    /// @param _endingPrice - Price of item (in wei) at end of auction.
1716:    /// @param _duration - Length of auction (in seconds).
1717:    /// @param _seller - Seller, if not the message sender
1718:    function createAuction(
1719:        uint256 _tokenId,
1720:        uint256 _startingPrice,
1721:        uint256 _endingPrice,
1722:        uint256 _duration,
1723:        address _seller
1724:    )
1725:        external
1726:    {
1727:        // Sanity check that no inputs overflow how many bits we've allocated
1728:        // to store them in the auction struct.
1729:        require(_startingPrice == uint256(uint128(_startingPrice)));
1730:        require(_endingPrice == uint256(uint128(_endingPrice)));
1731:        require(_duration == uint256(uint64(_duration)));
1732:
1733:        require(msg.sender == address(nonFungibleContract));
1734:        _escrow(_seller, _tokenId);
1735:        Auction memory auction = Auction(
1736:            _seller,
1737:            uint128(_startingPrice),
1738:            uint128(_endingPrice),
1739:            uint64(_duration),
1740:            uint64(now),
1741:            0
1742:        );
1743:        _addAuction(_tokenId, auction);
1744:    }
1745:
1746:    function createGen0Auction(
1747:        uint256 _tokenId,
1748:        uint256 _startingPrice,
1749:        uint256 _endingPrice,
1750:        uint256 _duration,
1751:        address _seller
1752:    )
1753:        external
1754:    {
1755:        // Sanity check that no inputs overflow how many bits we've allocated
1756:        // to store them in the auction struct.
1757:        require(_startingPrice == uint256(uint128(_startingPrice)));
1758:        require(_endingPrice == uint256(uint128(_endingPrice)));
1759:        require(_duration == uint256(uint64(_duration)));
1760:
1761:        require(msg.sender == address(nonFungibleContract));
1762:        _escrow(_seller, _tokenId);
1763:        Auction memory auction = Auction(
1764:            _seller,
1765:            uint128(_startingPrice),
1766:            uint128(_endingPrice),
1767:            uint64(_duration),
1768:            uint64(now),
1769:            1
1770:        );
1771:        _addAuction(_tokenId, auction);
1772:    }    
1773:
1774:    /// @dev Updates lastSalePrice if seller is the nft contract
1775:    /// Otherwise, works the same as default bid method.
1776:    function bid(uint256 _tokenId)
1777:        external
1778:        payable
1779:    {
1780:        // _bid verifies token ID size
1781:        uint64 isGen0 = tokenIdToAuction[_tokenId].isGen0;
1782:        uint256 price = _bid(_tokenId, msg.value);
1783:        _transfer(msg.sender, _tokenId);
1784:
1785:        // If not a gen0 auction, exit
1786:        if (isGen0 == 1) {
1787:            // Track gen0 sale prices
1788:            lastGen0SalePrices[gen0SaleCount % 5] = price;
1789:            gen0SaleCount++;
1790:        }
1791:    }
1792:
1793:    function createPanda(uint256 _tokenId,uint256 _type)
1794:        external
1795:    {
1796:        require(msg.sender == address(nonFungibleContract));
1797:        if (_type == 0) {
1798:            CommonPanda.push(_tokenId);
1799:        }else {
1800:            RarePanda.push(_tokenId);
1801:        }
1802:    }
1803:
1804:    function surprisePanda()
1805:        external
1806:        payable
1807:    {
1808:        bytes32 bHash = keccak256(block.blockhash(block.number),block.blockhash(block.number-1));
1809:        uint256 PandaIndex;
1810:        if (bHash[25] > 0xC8) {
1811:            require(uint256(RarePanda.length) >= RarePandaIndex);
1812:            PandaIndex = RarePandaIndex;
1813:            RarePandaIndex ++;
1814:
1815:        } else{
1816:            require(uint256(CommonPanda.length) >= CommonPandaIndex);
1817:            PandaIndex = CommonPandaIndex;
1818:            CommonPandaIndex ++;
1819:        }
1820:        _transfer(msg.sender,PandaIndex);
1821:    }
1822:
1823:    function packageCount() external view returns(uint256 common,uint256 surprise) {
1824:        common   = CommonPanda.length + 1 - CommonPandaIndex;
1825:        surprise = RarePanda.length + 1 - RarePandaIndex;
1826:    }
1827:
1828:    function averageGen0SalePrice() external view returns (uint256) {
1829:        uint256 sum = 0;
1830:        for (uint256 i = 0; i < 5; i++) {
1831:            sum += lastGen0SalePrices[i];
1832:        }
1833:        return sum / 5;
1834:    }
1835:
1836:}
