1943:        _transfer(msg.sender, _tokenId);
1944:        delete tokenIdToErc20Address[_tokenId];
1945:    }
1946:
1947:    function cancelAuction(uint256 _tokenId)
1948:        external
1949:    {
1950:        Auction storage auction = tokenIdToAuction[_tokenId];
1951:        require(_isOnAuction(auction));
1952:        address seller = auction.seller;
