439:            uint16 pureDegree = uint16(geneScience.getPureFromGene(_genes));
440:            if (pureDegree==0) {
441:                pureDegree = 1;
442:            }
443:            cooldownIndex = 1000/pureDegree;
444:            if (cooldownIndex%10 < 5){
445:                cooldownIndex = cooldownIndex/10;
446:            }else{
447:                cooldownIndex = cooldownIndex/10 + 1;
448:            }
449:            cooldownIndex = cooldownIndex - 1;
450:            if (cooldownIndex > 8) {
451:                cooldownIndex = 8;
452:            }
453:            uint256 _tp = geneScience.getWizzType(_genes);
454:            if (_tp>0 && wizzPandaQuota[_tp]<=wizzPandaCount[_tp]) {
455:                _genes = geneScience.clearWizzType(_genes);
456:                _tp = 0;
457:            }
458:            // gensis panda cooldownIndex should be 24 hours
459:            if (_tp == 1){
460:                cooldownIndex = 5;
461:            }
462:
463:            // increase wizz counter
464:            if (_tp>0){
465:                wizzPandaCount[_tp] = wizzPandaCount[_tp] + 1;
466:            }
467:            // all gen0&gen1 except gensis
468:            if (_generation <= 1 && _tp != 1){
469:                require(gen0CreatedCount<GEN0_TOTAL_COUNT);
470:                gen0CreatedCount++;
471:            }
472:        }
473:
474:        Panda memory _panda = Panda({
475:            genes: _genes,
476:            birthTime: uint64(now),
477:            cooldownEndBlock: 0,
478:            matronId: uint32(_matronId),
479:            sireId: uint32(_sireId),
480:            siringWithId: 0,
481:            cooldownIndex: cooldownIndex,
482:            generation: uint16(_generation)
483:        });
484:        uint256 newKittenId = pandas.push(_panda) - 1;
485:
486:        // It's probably never going to happen, 4 billion cats is A LOT, but
487:        // let's just be 100% sure we never let this happen.
488:        require(newKittenId == uint256(uint32(newKittenId)));
489:
490:        // emit the birth event
491:        Birth(
492:            _owner,
493:            newKittenId,
494:            uint256(_panda.matronId),
495:            uint256(_panda.sireId),
496:            _panda.genes
497:        );
498:
499:        // This will assign ownership, and also emit the Transfer event as
500:        // per ERC721 draft
501:        _transfer(0, _owner, newKittenId);
502:        
503:        return newKittenId;
504:    }
505:
506:    // Any C-level can fix how many seconds per blocks are currently observed.
507:    function setSecondsPerBlock(uint256 secs) external onlyCLevel {
508:        require(secs < cooldowns[0]);
509:        secondsPerBlock = secs;
510:    }
511:}
