789:/// @title A facet of PandaCore that manages Panda siring, gestation, and birth.
790:/// @author Axiom Zen (https://www.axiomzen.co)
791:/// @dev See the PandaCore contract documentation to understand how the various contract facets are arranged.
792:contract PandaBreeding is PandaOwnership {
793:
794:    uint256 public constant GENSIS_TOTAL_COUNT = 100;
795:
796:    /// @dev The Pregnant event is fired when two cats successfully breed and the pregnancy
797:    ///  timer begins for the matron.
798:    event Pregnant(address owner, uint256 matronId, uint256 sireId, uint256 cooldownEndBlock);
799:    /// @dev The Abortion event is fired when two cats breed failed.
800:    event Abortion(address owner, uint256 matronId, uint256 sireId);
801:
802:    /// @notice The minimum payment required to use breedWithAuto(). This fee goes towards
803:    ///  the gas cost paid by whatever calls giveBirth(), and can be dynamically updated by
804:    ///  the COO role as the gas price changes.
805:    uint256 public autoBirthFee = 2 finney;
806:
807:    // Keeps track of number of pregnant pandas.
808:    uint256 public pregnantPandas;
809:
810:    mapping(uint256 => address) childOwner;
811:
812:
813:    /// @dev Update the address of the genetic contract, can only be called by the CEO.
814:    /// @param _address An address of a GeneScience contract instance to be used from this point forward.
815:    function setGeneScienceAddress(address _address) external onlyCEO {
816:        GeneScienceInterface candidateContract = GeneScienceInterface(_address);
817:
818:        // NOTE: verify that a contract is what we expect - https://github.com/Lunyr/crowdsale-contracts/blob/cfadd15986c30521d8ba7d5b6f57b4fefcc7ac38/contracts/LunyrToken.sol#L117
819:        require(candidateContract.isGeneScience());
820:
821:        // Set the new contract address
822:        geneScience = candidateContract;
823:    }
824:
825:    /// @dev Checks that a given kitten is able to breed. Requires that the
826:    ///  current cooldown is finished (for sires) and also checks that there is
827:    ///  no pending pregnancy.
828:    function _isReadyToBreed(Panda _kit) internal view returns(bool) {
829:        // In addition to checking the cooldownEndBlock, we also need to check to see if
830:        // the cat has a pending birth; there can be some period of time between the end
831:        // of the pregnacy timer and the birth event.
832:        return (_kit.siringWithId == 0) && (_kit.cooldownEndBlock <= uint64(block.number));
833:    }
834:
835:    /// @dev Check if a sire has authorized breeding with this matron. True if both sire
836:    ///  and matron have the same owner, or if the sire has given siring permission to
837:    ///  the matron's owner (via approveSiring()).
838:    function _isSiringPermitted(uint256 _sireId, uint256 _matronId) internal view returns(bool) {
839:        address matronOwner = pandaIndexToOwner[_matronId];
840:        address sireOwner = pandaIndexToOwner[_sireId];
841:
842:        // Siring is okay if they have same owner, or if the matron's owner was given
843:        // permission to breed with this sire.
844:        return (matronOwner == sireOwner || sireAllowedToAddress[_sireId] == matronOwner);
845:    }
846:
847:    /// @dev Set the cooldownEndTime for the given Panda, based on its current cooldownIndex.
848:    ///  Also increments the cooldownIndex (unless it has hit the cap).
849:    /// @param _kitten A reference to the Panda in storage which needs its timer started.
850:    function _triggerCooldown(Panda storage _kitten) internal {
851:        // Compute an estimation of the cooldown time in blocks (based on current cooldownIndex).
852:        _kitten.cooldownEndBlock = uint64((cooldowns[_kitten.cooldownIndex] / secondsPerBlock) + block.number);
853:
854:
855:        // Increment the breeding count, clamping it at 13, which is the length of the
856:        // cooldowns array. We could check the array size dynamically, but hard-coding
857:        // this as a constant saves gas. Yay, Solidity!
858:        if (_kitten.cooldownIndex < 8 && geneScience.getWizzType(_kitten.genes) != 1) {
859:            _kitten.cooldownIndex += 1;
860:        }
861:    }
862:
863:    /// @notice Grants approval to another user to sire with one of your Pandas.
864:    /// @param _addr The address that will be able to sire with your Panda. Set to
865:    ///  address(0) to clear all siring approvals for this Panda.
866:    /// @param _sireId A Panda that you own that _addr will now be able to sire with.
867:    function approveSiring(address _addr, uint256 _sireId)
868:    external
869:    whenNotPaused {
870:        require(_owns(msg.sender, _sireId));
871:        sireAllowedToAddress[_sireId] = _addr;
872:    }
873:
874:    /// @dev Updates the minimum payment required for calling giveBirthAuto(). Can only
875:    ///  be called by the COO address. (This fee is used to offset the gas cost incurred
876:    ///  by the autobirth daemon).
877:    function setAutoBirthFee(uint256 val) external onlyCOO {
878:        autoBirthFee = val;
879:    }
880:
881:    /// @dev Checks to see if a given Panda is pregnant and (if so) if the gestation
882:    ///  period has passed.
883:    function _isReadyToGiveBirth(Panda _matron) private view returns(bool) {
884:        return (_matron.siringWithId != 0) && (_matron.cooldownEndBlock <= uint64(block.number));
885:    }
886:
887:    /// @notice Checks that a given kitten is able to breed (i.e. it is not pregnant or
888:    ///  in the middle of a siring cooldown).
889:    /// @param _pandaId reference the id of the kitten, any user can inquire about it
890:    function isReadyToBreed(uint256 _pandaId)
891:    public
892:    view
893:    returns(bool) {
894:        require(_pandaId > 0);
895:        Panda storage kit = pandas[_pandaId];
896:        return _isReadyToBreed(kit);
897:    }
898:
899:    /// @dev Checks whether a panda is currently pregnant.
900:    /// @param _pandaId reference the id of the kitten, any user can inquire about it
901:    function isPregnant(uint256 _pandaId)
902:    public
903:    view
904:    returns(bool) {
905:        require(_pandaId > 0);
906:        // A panda is pregnant if and only if this field is set
907:        return pandas[_pandaId].siringWithId != 0;
908:    }
909:
910:    /// @dev Internal check to see if a given sire and matron are a valid mating pair. DOES NOT
911:    ///  check ownership permissions (that is up to the caller).
912:    /// @param _matron A reference to the Panda struct of the potential matron.
913:    /// @param _matronId The matron's ID.
914:    /// @param _sire A reference to the Panda struct of the potential sire.
915:    /// @param _sireId The sire's ID
916:    function _isValidMatingPair(
917:        Panda storage _matron,
918:        uint256 _matronId,
919:        Panda storage _sire,
920:        uint256 _sireId
921:    )
922:    private
923:    view
924:    returns(bool) {
925:        // A Panda can't breed with itself!
926:        if (_matronId == _sireId) {
927:            return false;
928:        }
929:
930:        // Pandas can't breed with their parents.
931:        if (_matron.matronId == _sireId || _matron.sireId == _sireId) {
932:            return false;
933:        }
934:        if (_sire.matronId == _matronId || _sire.sireId == _matronId) {
935:            return false;
936:        }
937:
938:        // We can short circuit the sibling check (below) if either cat is
939:        // gen zero (has a matron ID of zero).
940:        if (_sire.matronId == 0 || _matron.matronId == 0) {
941:            return true;
942:        }
943:
944:        // Pandas can't breed with full or half siblings.
945:        if (_sire.matronId == _matron.matronId || _sire.matronId == _matron.sireId) {
946:            return false;
947:        }
948:        if (_sire.sireId == _matron.matronId || _sire.sireId == _matron.sireId) {
949:            return false;
950:        }
951:
952:        // male should get breed with female
953:        if (geneScience.getSex(_matron.genes) + geneScience.getSex(_sire.genes) != 1) {
954:            return false;
955:        }
956:
957:        // Everything seems cool! Let's get DTF.
958:        return true;
959:    }
960:
961:    /// @dev Internal check to see if a given sire and matron are a valid mating pair for
962:    ///  breeding via auction (i.e. skips ownership and siring approval checks).
963:    function _canBreedWithViaAuction(uint256 _matronId, uint256 _sireId)
964:    internal
965:    view
966:    returns(bool) {
967:        Panda storage matron = pandas[_matronId];
968:        Panda storage sire = pandas[_sireId];
969:        return _isValidMatingPair(matron, _matronId, sire, _sireId);
970:    }
971:
972:    /// @notice Checks to see if two cats can breed together, including checks for
973:    ///  ownership and siring approvals. Does NOT check that both cats are ready for
974:    ///  breeding (i.e. breedWith could still fail until the cooldowns are finished).
975:    ///  TODO: Shouldn't this check pregnancy and cooldowns?!?
976:    /// @param _matronId The ID of the proposed matron.
977:    /// @param _sireId The ID of the proposed sire.
978:    function canBreedWith(uint256 _matronId, uint256 _sireId)
979:    external
980:    view
981:    returns(bool) {
982:        require(_matronId > 0);
983:        require(_sireId > 0);
984:        Panda storage matron = pandas[_matronId];
