1966:    function _bidERC20(address _erc20Address,address _buyerAddress, uint256 _tokenId, uint256 _bidAmount)
1967:        internal
1968:        returns (uint256)
1969:    {
1970:        // Get a reference to the auction struct
1971:        Auction storage auction = tokenIdToAuction[_tokenId];
1972:
1973:        // Explicitly check that this auction is currently live.
1974:        // (Because of how Ethereum mappings work, we can't just count
1975:        // on the lookup above failing. An invalid _tokenId will just
1976:        // return an auction object that is all zeros.)
1977:        require(_isOnAuction(auction));
1978:
1979:
1980:        require (_erc20Address != address(0) && _erc20Address == tokenIdToErc20Address[_tokenId]);
1981:        
1982:
1983:        // Check that the bid is greater than or equal to the current price
1984:        uint256 price = _currentPrice(auction);
1985:        require(_bidAmount >= price);
1986:
1987:        // Grab a reference to the seller before the auction struct
1988:        // gets deleted.
1989:        address seller = auction.seller;
1990:
1991:        // The bid is good! Remove the auction before sending the fees
1992:        // to the sender so we can't have a reentrancy attack.
1993:        _removeAuction(_tokenId);
1994:
1995:        // Transfer proceeds to seller (if there are any!)
1996:        if (price > 0) {
1997:            // Calculate the auctioneer's cut.
1998:            // (NOTE: _computeCut() is guaranteed to return a
1999:            // value <= price, so this subtraction can't go negative.)
2000:            uint256 auctioneerCut = _computeCut(price);
2001:            uint256 sellerProceeds = price - auctioneerCut;
2002:
2003:            // Send Erc20 Token to seller should call Erc20 contract
2004:            // Reference to contract
2005:            require(ERC20(_erc20Address).transferFrom(_buyerAddress,seller,sellerProceeds));
2006:            if (auctioneerCut > 0){
2007:                require(ERC20(_erc20Address).transferFrom(_buyerAddress,address(this),auctioneerCut));
2008:                balances[_erc20Address] += auctioneerCut;
2009:            }
2010:        }
2011:
2012:        // Tell the world!
2013:        AuctionSuccessful(_tokenId, price, msg.sender);
2014:
2015:        return price;
