877:    function setAutoBirthFee(uint256 val) external onlyCOO {
878:        autoBirthFee = val;
879:    }
880:
881:    /// @dev Checks to see if a given Panda is pregnant and (if so) if the gestation
882:    ///  period has passed.
883:    function _isReadyToGiveBirth(Panda _matron) private view returns(bool) {
884:        return (_matron.siringWithId != 0) && (_matron.cooldownEndBlock <= uint64(block.number));
885:    }
886:
887:    /// @notice Checks that a given kitten is able to breed (i.e. it is not pregnant or
888:    ///  in the middle of a siring cooldown).
889:    /// @param _pandaId reference the id of the kitten, any user can inquire about it
890:    function isReadyToBreed(uint256 _pandaId)
891:    public
892:    view
893:    returns(bool) {
894:        require(_pandaId > 0);
895:        Panda storage kit = pandas[_pandaId];
896:        return _isReadyToBreed(kit);
897:    }
898:
899:    /// @dev Checks whether a panda is currently pregnant.
900:    /// @param _pandaId reference the id of the kitten, any user can inquire about it
901:    function isPregnant(uint256 _pandaId)
902:    public
903:    view
904:    returns(bool) {
905:        require(_pandaId > 0);
906:        // A panda is pregnant if and only if this field is set
907:        return pandas[_pandaId].siringWithId != 0;
908:    }
909:
910:    /// @dev Internal check to see if a given sire and matron are a valid mating pair. DOES NOT
911:    ///  check ownership permissions (that is up to the caller).
912:    /// @param _matron A reference to the Panda struct of the potential matron.
913:    /// @param _matronId The matron's ID.
914:    /// @param _sire A reference to the Panda struct of the potential sire.
915:    /// @param _sireId The sire's ID
916:    function _isValidMatingPair(
917:        Panda storage _matron,
918:        uint256 _matronId,
919:        Panda storage _sire,
920:        uint256 _sireId
921:    )
922:    private
923:    view
924:    returns(bool) {
925:        // A Panda can't breed with itself!
926:        if (_matronId == _sireId) {
927:            return false;
928:        }
929:
930:        // Pandas can't breed with their parents.
931:        if (_matron.matronId == _sireId || _matron.sireId == _sireId) {
932:            return false;
933:        }
934:        if (_sire.matronId == _matronId || _sire.sireId == _matronId) {
935:            return false;
936:        }
937:
938:        // We can short circuit the sibling check (below) if either cat is
939:        // gen zero (has a matron ID of zero).
940:        if (_sire.matronId == 0 || _matron.matronId == 0) {
941:            return true;
942:        }
943:
944:        // Pandas can't breed with full or half siblings.
945:        if (_sire.matronId == _matron.matronId || _sire.matronId == _matron.sireId) {
946:            return false;
947:        }
948:        if (_sire.sireId == _matron.matronId || _sire.sireId == _matron.sireId) {
949:            return false;
950:        }
951:
952:        // male should get breed with female
953:        if (geneScience.getSex(_matron.genes) + geneScience.getSex(_sire.genes) != 1) {
954:            return false;
955:        }
956:
957:        // Everything seems cool! Let's get DTF.
958:        return true;
959:    }
960:
961:    /// @dev Internal check to see if a given sire and matron are a valid mating pair for
962:    ///  breeding via auction (i.e. skips ownership and siring approval checks).
963:    function _canBreedWithViaAuction(uint256 _matronId, uint256 _sireId)
964:    internal
965:    view
966:    returns(bool) {
967:        Panda storage matron = pandas[_matronId];
968:        Panda storage sire = pandas[_sireId];
969:        return _isValidMatingPair(matron, _matronId, sire, _sireId);
970:    }
971:
972:    /// @notice Checks to see if two cats can breed together, including checks for
973:    ///  ownership and siring approvals. Does NOT check that both cats are ready for
974:    ///  breeding (i.e. breedWith could still fail until the cooldowns are finished).
975:    ///  TODO: Shouldn't this check pregnancy and cooldowns?!?
976:    /// @param _matronId The ID of the proposed matron.
977:    /// @param _sireId The ID of the proposed sire.
978:    function canBreedWith(uint256 _matronId, uint256 _sireId)
979:    external
980:    view
981:    returns(bool) {
982:        require(_matronId > 0);
983:        require(_sireId > 0);
984:        Panda storage matron = pandas[_matronId];
985:        Panda storage sire = pandas[_sireId];
986:        return _isValidMatingPair(matron, _matronId, sire, _sireId) &&
987:            _isSiringPermitted(_sireId, _matronId);
988:    }
989:
990:    function _exchangeMatronSireId(uint256 _matronId, uint256 _sireId) internal returns(uint256, uint256) {
991:        if (geneScience.getSex(pandas[_matronId].genes) == 1) {
992:            return (_sireId, _matronId);
993:        } else {
994:            return (_matronId, _sireId);
995:        }
996:    }
997:
998:    /// @dev Internal utility function to initiate breeding, assumes that all breeding
999:    ///  requirements have been checked.
1000:    function _breedWith(uint256 _matronId, uint256 _sireId, address _owner) internal {
1001:        // make id point real gender
1002:        (_matronId, _sireId) = _exchangeMatronSireId(_matronId, _sireId);
1003:        // Grab a reference to the Pandas from storage.
1004:        Panda storage sire = pandas[_sireId];
1005:        Panda storage matron = pandas[_matronId];
1006:
1007:        // Mark the matron as pregnant, keeping track of who the sire is.
1008:        matron.siringWithId = uint32(_sireId);
1009:
1010:        // Trigger the cooldown for both parents.
1011:        _triggerCooldown(sire);
1012:        _triggerCooldown(matron);
1013:
1014:        // Clear siring permission for both parents. This may not be strictly necessary
1015:        // but it's likely to avoid confusion!
1016:        delete sireAllowedToAddress[_matronId];
1017:        delete sireAllowedToAddress[_sireId];
1018:
1019:        // Every time a panda gets pregnant, counter is incremented.
1020:        pregnantPandas++;
1021:
1022:        childOwner[_matronId] = _owner;
1023:
1024:        // Emit the pregnancy event.
1025:        Pregnant(pandaIndexToOwner[_matronId], _matronId, _sireId, matron.cooldownEndBlock);
1026:    }
1027:
1028:    /// @notice Breed a Panda you own (as matron) with a sire that you own, or for which you
1029:    ///  have previously been given Siring approval. Will either make your cat pregnant, or will
1030:    ///  fail entirely. Requires a pre-payment of the fee given out to the first caller of giveBirth()
1031:    /// @param _matronId The ID of the Panda acting as matron (will end up pregnant if successful)
1032:    /// @param _sireId The ID of the Panda acting as sire (will begin its siring cooldown if successful)
1033:    function breedWithAuto(uint256 _matronId, uint256 _sireId)
1034:    external
1035:    payable
1036:    whenNotPaused {
1037:        // Checks for payment.
1038:        require(msg.value >= autoBirthFee);
1039:
1040:        // Caller must own the matron.
1041:        require(_owns(msg.sender, _matronId));
1042:
1043:        // Neither sire nor matron are allowed to be on auction during a normal
1044:        // breeding operation, but we don't need to check that explicitly.
1045:        // For matron: The caller of this function can't be the owner of the matron
1046:        //   because the owner of a Panda on auction is the auction house, and the
1047:        //   auction house will never call breedWith().
1048:        // For sire: Similarly, a sire on auction will be owned by the auction house
1049:        //   and the act of transferring ownership will have cleared any oustanding
1050:        //   siring approval.
1051:        // Thus we don't need to spend gas explicitly checking to see if either cat
1052:        // is on auction.
1053:
1054:        // Check that matron and sire are both owned by caller, or that the sire
1055:        // has given siring permission to caller (i.e. matron's owner).
1056:        // Will fail for _sireId = 0
1057:        require(_isSiringPermitted(_sireId, _matronId));
1058:
1059:        // Grab a reference to the potential matron
1060:        Panda storage matron = pandas[_matronId];
1061:
1062:        // Make sure matron isn't pregnant, or in the middle of a siring cooldown
1063:        require(_isReadyToBreed(matron));
1064:
1065:        // Grab a reference to the potential sire
1066:        Panda storage sire = pandas[_sireId];
1067:
1068:        // Make sure sire isn't pregnant, or in the middle of a siring cooldown
1069:        require(_isReadyToBreed(sire));
1070:
1071:        // Test that these cats are a valid mating pair.
1072:        require(_isValidMatingPair(
1073:            matron,
1074:            _matronId,
1075:            sire,
1076:            _sireId
1077:        ));
1078:
1079:        // All checks passed, panda gets pregnant!
1080:        _breedWith(_matronId, _sireId, msg.sender);
1081:    }
1082:
1083:    /// @notice Have a pregnant Panda give birth!
1084:    /// @param _matronId A Panda ready to give birth.
1085:    /// @return The Panda ID of the new kitten.
1086:    /// @dev Looks at a given Panda and, if pregnant and if the gestation period has passed,
1087:    ///  combines the genes of the two parents to create a new kitten. The new Panda is assigned
1088:    ///  to the current owner of the matron. Upon successful completion, both the matron and the
1089:    ///  new kitten will be ready to breed again. Note that anyone can call this function (if they
1090:    ///  are willing to pay the gas!), but the new kitten always goes to the mother's owner.
1091:    function giveBirth(uint256 _matronId, uint256[2] _childGenes, uint256[2] _factors)
1092:    external
1093:    whenNotPaused
1094:    onlyCLevel
1095:    returns(uint256) {
1096:        // Grab a reference to the matron in storage.
1097:        Panda storage matron = pandas[_matronId];
1098:
1099:        // Check that the matron is a valid cat.
1100:        require(matron.birthTime != 0);
1101:
1102:        // Check that the matron is pregnant, and that its time has come!
1103:        require(_isReadyToGiveBirth(matron));
1104:
1105:        // Grab a reference to the sire in storage.
1106:        uint256 sireId = matron.siringWithId;
1107:        Panda storage sire = pandas[sireId];
1108:
1109:        // Determine the higher generation number of the two parents
1110:        uint16 parentGen = matron.generation;
1111:        if (sire.generation > matron.generation) {
1112:            parentGen = sire.generation;
1113:        }
1114:
1115:        // Call the sooper-sekret gene mixing operation.
1116:        //uint256[2] memory childGenes = geneScience.mixGenes(matron.genes, sire.genes,matron.generation,sire.generation, matron.cooldownEndBlock - 1);
1117:        uint256[2] memory childGenes = _childGenes;
1118:
1119:        uint256 kittenId = 0;
1120:
1121:        // birth failed
1122:        uint256 probability = (geneScience.getPureFromGene(matron.genes) + geneScience.getPureFromGene(sire.genes)) / 2 + _factors[0];
1123:        if (probability >= (parentGen + 1) * _factors[1]) {
1124:            probability = probability - (parentGen + 1) * _factors[1];
1125:        } else {
1126:            probability = 0;
1127:        }
1128:        if (parentGen == 0 && gen0CreatedCount == GEN0_TOTAL_COUNT) {
1129:            probability = 0;
1130:        }
1131:        if (uint256(keccak256(block.blockhash(block.number - 2), now)) % 100 < probability) {
1132:            // Make the new kitten!
1133:            address owner = childOwner[_matronId];
1134:            kittenId = _createPanda(_matronId, matron.siringWithId, parentGen + 1, childGenes, owner);
1135:        } else {
1136:            Abortion(pandaIndexToOwner[_matronId], _matronId, sireId);
1137:        }
1138:        // Make the new kitten!
1139:        //address owner = pandaIndexToOwner[_matronId];
1140:        //address owner = childOwner[_matronId];
1141:        //uint256 kittenId = _createPanda(_matronId, matron.siringWithId, parentGen + 1, childGenes, owner);
1142:
1143:        // Clear the reference to sire from the matron (REQUIRED! Having siringWithId
1144:        // set is what marks a matron as being pregnant.)
1145:        delete matron.siringWithId;
1146:
1147:        // Every time a panda gives birth counter is decremented.
1148:        pregnantPandas--;
1149:
1150:        // Send the balance fee to the person who made birth happen.
1151:         // <yes> <report> UNCHECKED_LL_CALLS
1152:        msg.sender.send(autoBirthFee);
1153:
1154:        delete childOwner[_matronId];
1155:
1156:        // return the new kitten's ID
1157:        return kittenId;
1158:    }
1159:}
