1165:/// @title Auction Core
1166:/// @dev Contains models, variables, and internal methods for the auction.
1167:/// @notice We omit a fallback function to prevent accidental sends to this contract.
1168:contract ClockAuctionBase {
1169:
1170:    // Represents an auction on an NFT
1171:    struct Auction {
1172:        // Current owner of NFT
1173:        address seller;
1174:        // Price (in wei) at beginning of auction
1175:        uint128 startingPrice;
1176:        // Price (in wei) at end of auction
1177:        uint128 endingPrice;
1178:        // Duration (in seconds) of auction
1179:        uint64 duration;
1180:        // Time when auction started
1181:        // NOTE: 0 if this auction has been concluded
1182:        uint64 startedAt;
1183:        // is this auction for gen0 panda
1184:        uint64 isGen0;
1185:    }
1186:
1187:    // Reference to contract tracking NFT ownership
1188:    ERC721 public nonFungibleContract;
1189:
1190:    // Cut owner takes on each auction, measured in basis points (1/100 of a percent).
1191:    // Values 0-10,000 map to 0%-100%
1192:    uint256 public ownerCut;
1193:
1194:    // Map from token ID to their corresponding auction.
1195:    mapping (uint256 => Auction) tokenIdToAuction;
1196:
1197:    event AuctionCreated(uint256 tokenId, uint256 startingPrice, uint256 endingPrice, uint256 duration);
1198:    event AuctionSuccessful(uint256 tokenId, uint256 totalPrice, address winner);
1199:    event AuctionCancelled(uint256 tokenId);
1200:
1201:    /// @dev Returns true if the claimant owns the token.
1202:    /// @param _claimant - Address claiming to own the token.
1203:    /// @param _tokenId - ID of token whose ownership to verify.
1204:    function _owns(address _claimant, uint256 _tokenId) internal view returns (bool) {
1205:        return (nonFungibleContract.ownerOf(_tokenId) == _claimant);
1206:    }
1207:
1208:    /// @dev Escrows the NFT, assigning ownership to this contract.
1209:    /// Throws if the escrow fails.
1210:    /// @param _owner - Current owner address of token to escrow.
1211:    /// @param _tokenId - ID of token whose approval to verify.
1212:    function _escrow(address _owner, uint256 _tokenId) internal {
1213:        // it will throw if transfer fails
1214:        nonFungibleContract.transferFrom(_owner, this, _tokenId);
1215:    }
1216:
1217:    /// @dev Transfers an NFT owned by this contract to another address.
1218:    /// Returns true if the transfer succeeds.
1219:    /// @param _receiver - Address to transfer NFT to.
1220:    /// @param _tokenId - ID of token to transfer.
1221:    function _transfer(address _receiver, uint256 _tokenId) internal {
1222:        // it will throw if transfer fails
1223:        nonFungibleContract.transfer(_receiver, _tokenId);
1224:    }
1225:
1226:    /// @dev Adds an auction to the list of open auctions. Also fires the
1227:    ///  AuctionCreated event.
1228:    /// @param _tokenId The ID of the token to be put on auction.
1229:    /// @param _auction Auction to add.
1230:    function _addAuction(uint256 _tokenId, Auction _auction) internal {
1231:        // Require that all auctions have a duration of
1232:        // at least one minute. (Keeps our math from getting hairy!)
1233:        require(_auction.duration >= 1 minutes);
1234:
1235:        tokenIdToAuction[_tokenId] = _auction;
1236:
1237:        AuctionCreated(
1238:            uint256(_tokenId),
1239:            uint256(_auction.startingPrice),
1240:            uint256(_auction.endingPrice),
1241:            uint256(_auction.duration)
1242:        );
1243:    } 
1244:
1245:    /// @dev Cancels an auction unconditionally.
1246:    function _cancelAuction(uint256 _tokenId, address _seller) internal {
1247:        _removeAuction(_tokenId);
1248:        _transfer(_seller, _tokenId);
1249:        AuctionCancelled(_tokenId);
1250:    }
1251:
1252:    /// @dev Computes the price and transfers winnings.
1253:    /// Does NOT transfer ownership of token.
1254:    function _bid(uint256 _tokenId, uint256 _bidAmount)
1255:        internal
1256:        returns (uint256)
1257:    {
1258:        // Get a reference to the auction struct
1259:        Auction storage auction = tokenIdToAuction[_tokenId];
1260:
1261:        // Explicitly check that this auction is currently live.
1262:        // (Because of how Ethereum mappings work, we can't just count
1263:        // on the lookup above failing. An invalid _tokenId will just
1264:        // return an auction object that is all zeros.)
1265:        require(_isOnAuction(auction));
1266:
1267:        // Check that the bid is greater than or equal to the current price
1268:        uint256 price = _currentPrice(auction);
1269:        require(_bidAmount >= price);
1270:
1271:        // Grab a reference to the seller before the auction struct
1272:        // gets deleted.
1273:        address seller = auction.seller;
1274:
1275:        // The bid is good! Remove the auction before sending the fees
1276:        // to the sender so we can't have a reentrancy attack.
1277:        _removeAuction(_tokenId);
1278:
1279:        // Transfer proceeds to seller (if there are any!)
1280:        if (price > 0) {
1281:            // Calculate the auctioneer's cut.
1282:            // (NOTE: _computeCut() is guaranteed to return a
1283:            // value <= price, so this subtraction can't go negative.)
1284:            uint256 auctioneerCut = _computeCut(price);
1285:            uint256 sellerProceeds = price - auctioneerCut;
1286:
1287:            // NOTE: Doing a transfer() in the middle of a complex
1288:            // method like this is generally discouraged because of
1289:            // reentrancy attacks and DoS attacks if the seller is
1290:            // a contract with an invalid fallback function. We explicitly
1291:            // guard against reentrancy attacks by removing the auction
1292:            // before calling transfer(), and the only thing the seller
1293:            // can DoS is the sale of their own asset! (And if it's an
1294:            // accident, they can call cancelAuction(). )
1295:            seller.transfer(sellerProceeds);
1296:        }
1297:
1298:        // Calculate any excess funds included with the bid. If the excess
1299:        // is anything worth worrying about, transfer it back to bidder.
1300:        // NOTE: We checked above that the bid amount is greater than or
1301:        // equal to the price so this cannot underflow.
1302:        uint256 bidExcess = _bidAmount - price;
1303:
1304:        // Return the funds. Similar to the previous transfer, this is
1305:        // not susceptible to a re-entry attack because the auction is
1306:        // removed before any transfers occur.
1307:        msg.sender.transfer(bidExcess);
1308:
1309:        // Tell the world!
1310:        AuctionSuccessful(_tokenId, price, msg.sender);
1311:
1312:        return price;
1313:    }
1314:
1315:
1316:
1317:    /// @dev Removes an auction from the list of open auctions.
1318:    /// @param _tokenId - ID of NFT on auction.
1319:    function _removeAuction(uint256 _tokenId) internal {
1320:        delete tokenIdToAuction[_tokenId];
1321:    }
1322:
1323:    /// @dev Returns true if the NFT is on auction.
1324:    /// @param _auction - Auction to check.
1325:    function _isOnAuction(Auction storage _auction) internal view returns (bool) {
1326:        return (_auction.startedAt > 0);
1327:    }
1328:
1329:    /// @dev Returns current price of an NFT on auction. Broken into two
1330:    ///  functions (this one, that computes the duration from the auction
1331:    ///  structure, and the other that does the price computation) so we
1332:    ///  can easily test that the price computation works correctly.
1333:    function _currentPrice(Auction storage _auction)
1334:        internal
1335:        view
1336:        returns (uint256)
1337:    {
1338:        uint256 secondsPassed = 0;
1339:
1340:        // A bit of insurance against negative values (or wraparound).
1341:        // Probably not necessary (since Ethereum guarnatees that the
1342:        // now variable doesn't ever go backwards).
1343:        if (now > _auction.startedAt) {
1344:            secondsPassed = now - _auction.startedAt;
1345:        }
1346:
1347:        return _computeCurrentPrice(
1348:            _auction.startingPrice,
1349:            _auction.endingPrice,
1350:            _auction.duration,
1351:            secondsPassed
1352:        );
1353:    }
1354:
1355:    /// @dev Computes the current price of an auction. Factored out
1356:    ///  from _currentPrice so we can run extensive unit tests.
1357:    ///  When testing, make this function public and turn on
1358:    ///  `Current price computation` test suite.
1359:    function _computeCurrentPrice(
1360:        uint256 _startingPrice,
1361:        uint256 _endingPrice,
1362:        uint256 _duration,
1363:        uint256 _secondsPassed
1364:    )
1365:        internal
1366:        pure
1367:        returns (uint256)
1368:    {
1369:        // NOTE: We don't use SafeMath (or similar) in this function because
1370:        //  all of our public functions carefully cap the maximum values for
1371:        //  time (at 64-bits) and currency (at 128-bits). _duration is
1372:        //  also known to be non-zero (see the require() statement in
1373:        //  _addAuction())
1374:        if (_secondsPassed >= _duration) {
1375:            // We've reached the end of the dynamic pricing portion
1376:            // of the auction, just return the end price.
1377:            return _endingPrice;
1378:        } else {
1379:            // Starting price can be higher than ending price (and often is!), so
1380:            // this delta can be negative.
1381:            int256 totalPriceChange = int256(_endingPrice) - int256(_startingPrice);
1382:
1383:            // This multiplication can't overflow, _secondsPassed will easily fit within
1384:            // 64-bits, and totalPriceChange will easily fit within 128-bits, their product
1385:            // will always fit within 256-bits.
1386:            int256 currentPriceChange = totalPriceChange * int256(_secondsPassed) / int256(_duration);
1387:
1388:            // currentPriceChange can be negative, but if so, will have a magnitude
1389:            // less that _startingPrice. Thus, this result will always end up positive.
1390:            int256 currentPrice = int256(_startingPrice) + currentPriceChange;
1391:
1392:            return uint256(currentPrice);
1393:        }
1394:    }
1395:
1396:    /// @dev Computes owner's cut of a sale.
1397:    /// @param _price - Sale price of NFT.
1398:    function _computeCut(uint256 _price) internal view returns (uint256) {
1399:        // NOTE: We don't use SafeMath (or similar) in this function because
1400:        //  all of our entry functions carefully cap the maximum values for
1401:        //  currency (at 128-bits), and ownerCut <= 10000 (see the require()
1402:        //  statement in the ClockAuction constructor). The result of this
1403:        //  function is always guaranteed to be <= _price.
1404:        return _price * ownerCut / 10000;
1405:    }
1406:
1407:}
