1413: * @title Pausable
1414: * @dev Base contract which allows children to implement an emergency stop mechanism.
1415: */
1416:contract Pausable is Ownable {
1417:  event Pause();
1418:  event Unpause();
1419:
1420:  bool public paused = false;
1421:
1422:
1423:  /**
1424:   * @dev modifier to allow actions only when the contract IS paused
1425:   */
1426:  modifier whenNotPaused() {
1427:    require(!paused);
1428:    _;
1429:  }
1430:
1431:  /**
1432:   * @dev modifier to allow actions only when the contract IS NOT paused
1433:   */
1434:  modifier whenPaused {
1435:    require(paused);
1436:    _;
1437:  }
1438:
1439:  /**
1440:   * @dev called by the owner to pause, triggers stopped state
1441:   */
1442:  function pause() onlyOwner whenNotPaused returns (bool) {
1443:    paused = true;
1444:    Pause();
1445:    return true;
1446:  }
1447:
1448:  /**
1449:   * @dev called by the owner to unpause, returns to normal state
1450:   */
1451:  function unpause() onlyOwner whenPaused returns (bool) {
1452:    paused = false;
1453:    Unpause();
1454:    return true;
1455:  }
1456:}
