1459:/// @title Clock auction for non-fungible tokens.
1460:/// @notice We omit a fallback function to prevent accidental sends to this contract.
1461:contract ClockAuction is Pausable, ClockAuctionBase {
1462:
1463:    /// @dev The ERC-165 interface signature for ERC-721.
1464:    ///  Ref: https://github.com/ethereum/EIPs/issues/165
1465:    ///  Ref: https://github.com/ethereum/EIPs/issues/721
1466:    bytes4 constant InterfaceSignature_ERC721 = bytes4(0x9a20483d);
1467:
1468:    /// @dev Constructor creates a reference to the NFT ownership contract
1469:    ///  and verifies the owner cut is in the valid range.
1470:    /// @param _nftAddress - address of a deployed contract implementing
1471:    ///  the Nonfungible Interface.
1472:    /// @param _cut - percent cut the owner takes on each auction, must be
1473:    ///  between 0-10,000.
1474:    function ClockAuction(address _nftAddress, uint256 _cut) public {
1475:        require(_cut <= 10000);
1476:        ownerCut = _cut;
1477:
1478:        ERC721 candidateContract = ERC721(_nftAddress);
1479:        require(candidateContract.supportsInterface(InterfaceSignature_ERC721));
1480:        nonFungibleContract = candidateContract;
1481:    }
1482:
1483:    /// @dev Remove all Ether from the contract, which is the owner's cuts
1484:    ///  as well as any Ether sent directly to the contract address.
1485:    ///  Always transfers to the NFT contract, but can be called either by
1486:    ///  the owner or the NFT contract.
1487:    function withdrawBalance() external {
1488:        address nftAddress = address(nonFungibleContract);
1489:
1490:        require(
1491:            msg.sender == owner ||
1492:            msg.sender == nftAddress
1493:        );
1494:        // We are using this boolean method to make sure that even if one fails it will still work
1495:        // <yes> <report> UNCHECKED_LL_CALLS
1496:        bool res = nftAddress.send(this.balance);
1497:    }
1498:
1499:    /// @dev Creates and begins a new auction.
1500:    /// @param _tokenId - ID of token to auction, sender must be owner.
1501:    /// @param _startingPrice - Price of item (in wei) at beginning of auction.
1502:    /// @param _endingPrice - Price of item (in wei) at end of auction.
1503:    /// @param _duration - Length of time to move between starting
1504:    ///  price and ending price (in seconds).
1505:    /// @param _seller - Seller, if not the message sender
1506:    function createAuction(
1507:        uint256 _tokenId,
1508:        uint256 _startingPrice,
1509:        uint256 _endingPrice,
1510:        uint256 _duration,
1511:        address _seller
1512:    )
1513:        external
1514:        whenNotPaused
1515:    {
1516:        // Sanity check that no inputs overflow how many bits we've allocated
1517:        // to store them in the auction struct.
1518:        require(_startingPrice == uint256(uint128(_startingPrice)));
1519:        require(_endingPrice == uint256(uint128(_endingPrice)));
1520:        require(_duration == uint256(uint64(_duration)));
1521:
1522:        require(_owns(msg.sender, _tokenId));
1523:        _escrow(msg.sender, _tokenId);
1524:        Auction memory auction = Auction(
1525:            _seller,
1526:            uint128(_startingPrice),
1527:            uint128(_endingPrice),
1528:            uint64(_duration),
1529:            uint64(now),
1530:            0
1531:        );
1532:        _addAuction(_tokenId, auction);
1533:    }
1534:
1535:    /// @dev Bids on an open auction, completing the auction and transferring
1536:    ///  ownership of the NFT if enough Ether is supplied.
1537:    /// @param _tokenId - ID of token to bid on.
1538:    function bid(uint256 _tokenId)
1539:        external
1540:        payable
1541:        whenNotPaused
1542:    {
1543:        // _bid will throw if the bid or funds transfer fails
1544:        _bid(_tokenId, msg.value);
1545:        _transfer(msg.sender, _tokenId);
1546:    }
1547:
1548:    /// @dev Cancels an auction that hasn't been won yet.
1549:    ///  Returns the NFT to original owner.
1550:    /// @notice This is a state-modifying function that can
1551:    ///  be called while the contract is paused.
1552:    /// @param _tokenId - ID of token on auction
1553:    function cancelAuction(uint256 _tokenId)
1554:        external
1555:    {
1556:        Auction storage auction = tokenIdToAuction[_tokenId];
1557:        require(_isOnAuction(auction));
1558:        address seller = auction.seller;
1559:        require(msg.sender == seller);
1560:        _cancelAuction(_tokenId, seller);
1561:    }
1562:
1563:    /// @dev Cancels an auction when the contract is paused.
1564:    ///  Only the owner may do this, and NFTs are returned to
1565:    ///  the seller. This should only be used in emergencies.
1566:    /// @param _tokenId - ID of the NFT on auction to cancel.
1567:    function cancelAuctionWhenPaused(uint256 _tokenId)
1568:        whenPaused
1569:        onlyOwner
1570:        external
1571:    {
1572:        Auction storage auction = tokenIdToAuction[_tokenId];
1573:        require(_isOnAuction(auction));
1574:        _cancelAuction(_tokenId, auction.seller);
1575:    }
1576:
1577:    /// @dev Returns auction info for an NFT on auction.
1578:    /// @param _tokenId - ID of NFT on auction.
1579:    function getAuction(uint256 _tokenId)
1580:        external
1581:        view
1582:        returns
1583:    (
1584:        address seller,
1585:        uint256 startingPrice,
1586:        uint256 endingPrice,
1587:        uint256 duration,
1588:        uint256 startedAt
1589:    ) {
1590:        Auction storage auction = tokenIdToAuction[_tokenId];
1591:        require(_isOnAuction(auction));
1592:        return (
1593:            auction.seller,
1594:            auction.startingPrice,
1595:            auction.endingPrice,
1596:            auction.duration,
1597:            auction.startedAt
1598:        );
1599:    }
1600:
1601:    /// @dev Returns the current price of an auction.
1602:    /// @param _tokenId - ID of the token price we are checking.
1603:    function getCurrentPrice(uint256 _tokenId)
1604:        external
1605:        view
1606:        returns (uint256)
1607:    {
1608:        Auction storage auction = tokenIdToAuction[_tokenId];
1609:        require(_isOnAuction(auction));
1610:        return _currentPrice(auction);
1611:    }
1612:
1613:}
