554:        bytes4(keccak256('name()')) ^
555:        bytes4(keccak256('symbol()')) ^
556:        bytes4(keccak256('totalSupply()')) ^
557:        bytes4(keccak256('balanceOf(address)')) ^
558:        bytes4(keccak256('ownerOf(uint256)')) ^
559:        bytes4(keccak256('approve(address,uint256)')) ^
560:        bytes4(keccak256('transfer(address,uint256)')) ^
561:        bytes4(keccak256('transferFrom(address,address,uint256)')) ^
