569:    {
570:        // DEBUG ONLY
571:        //require((InterfaceSignature_ERC165 == 0x01ffc9a7) && (InterfaceSignature_ERC721 == 0x9a20483d));
572:
573:        return ((_interfaceID == InterfaceSignature_ERC165) || (_interfaceID == InterfaceSignature_ERC721));
574:    }
575:
576:    // Internal utility functions: These functions all assume that their input arguments
577:    // are valid. We leave it to public methods to sanitize their inputs and follow
578:    // the required logic.
579:
580:    /// @dev Checks if a given address is the current owner of a particular Panda.
581:    /// @param _claimant the address we are validating against.
