1355:    /// @dev Computes the current price of an auction. Factored out
1356:    ///  from _currentPrice so we can run extensive unit tests.
1357:    ///  When testing, make this function public and turn on
1358:    ///  `Current price computation` test suite.
1359:    function _computeCurrentPrice(
1360:        uint256 _startingPrice,
1361:        uint256 _endingPrice,
1362:        uint256 _duration,
1363:        uint256 _secondsPassed
1364:    )
1365:        internal
1366:        pure
1367:        returns (uint256)
1368:    {
1369:        // NOTE: We don't use SafeMath (or similar) in this function because
1370:        //  all of our public functions carefully cap the maximum values for
1371:        //  time (at 64-bits) and currency (at 128-bits). _duration is
1372:        //  also known to be non-zero (see the require() statement in
1373:        //  _addAuction())
1374:        if (_secondsPassed >= _duration) {
1375:            // We've reached the end of the dynamic pricing portion
1376:            // of the auction, just return the end price.
1377:            return _endingPrice;
1378:        } else {
1379:            // Starting price can be higher than ending price (and often is!), so
1380:            // this delta can be negative.
1381:            int256 totalPriceChange = int256(_endingPrice) - int256(_startingPrice);
1382:
1383:            // This multiplication can't overflow, _secondsPassed will easily fit within
1384:            // 64-bits, and totalPriceChange will easily fit within 128-bits, their product
1385:            // will always fit within 256-bits.
1386:            int256 currentPriceChange = totalPriceChange * int256(_secondsPassed) / int256(_duration);
1387:
1388:            // currentPriceChange can be negative, but if so, will have a magnitude
1389:            // less that _startingPrice. Thus, this result will always end up positive.
1390:            int256 currentPrice = int256(_startingPrice) + currentPriceChange;
1391:
1392:            return uint256(currentPrice);
