100:    function request(uint8 requestType, address callbackAddr, bytes4 callbackFID, uint timestamp, bytes32[] requestData) public payable returns (int) {
101:        if (externalCallFlag) {
102:            throw;
103:        }
104:
105:        if (killswitch) {
106:            externalCallFlag = true;
107:            if (!msg.sender.call.value(msg.value)()) {
108:                throw;
109:            }
110:            externalCallFlag = false;
111:            return newVersion;
112:        }
113:
114:        if (msg.value < MIN_FEE) {
115:            externalCallFlag = true;
116:            // If the amount of ether sent by the requester is too little or 
117:            // too much, refund the requester and discard the request.
118:            if (!msg.sender.call.value(msg.value)()) {
119:                throw;
120:            }
121:            externalCallFlag = false;
122:            return FAIL_FLAG;
123:        } else {
124:            // Record the request.
125:            uint64 requestId = requestCnt;
126:            requestCnt++;
127:            unrespondedCnt++;
128:
129:            bytes32 paramsHash = sha3(requestType, requestData);
130:            requests[requestId].requester = msg.sender;
131:            requests[requestId].fee = msg.value;
132:            requests[requestId].callbackAddr = callbackAddr;
133:            requests[requestId].callbackFID = callbackFID;
134:            requests[requestId].paramsHash = paramsHash;
135:
136:            // Log the request for the Town Crier server to process.
137:            RequestInfo(requestId, requestType, msg.sender, msg.value, callbackAddr, paramsHash, timestamp, requestData);
138:            return requestId;
139:        }
140:    }
