150:        }
151:
152:        uint fee = requests[requestId].fee;
153:        if (requests[requestId].paramsHash != paramsHash) {
154:            // If the hash of request parameters in the response is not 
155:            // correct, discard the response for security concern.
156:            return;
157:        } else if (fee == CANCELLED_FEE_FLAG) {
158:            // If the request is cancelled by the requester, cancellation 
159:            // fee goes to the SGX account and set the request as having
160:            // been responded to.
161:            // <yes> <report> UNCHECKED_LL_CALLS
162:            SGX_ADDRESS.send(CANCELLATION_FEE);
163:            requests[requestId].fee = DELIVERED_FEE_FLAG;
164:            unrespondedCnt--;
165:            return;
166:        }
167:
168:        requests[requestId].fee = DELIVERED_FEE_FLAG;
169:        unrespondedCnt--;
170:
171:        if (error < 2) {
172:            // Either no error occurs, or the requester sent an invalid query.
173:            // Send the fee to the SGX account for its delivering.
174:            // <yes> <report> UNCHECKED_LL_CALLS
175:            SGX_ADDRESS.send(fee);         
176:        } else {
177:            // Error in TC, refund the requester.
178:            externalCallFlag = true;
179:            // <yes> <report> UNCHECKED_LL_CALLS
180:            requests[requestId].requester.call.gas(2300).value(fee)();
181:            externalCallFlag = false;
182:        }
183:
184:        uint callbackGas = (fee - MIN_FEE) / tx.gasprice; // gas left for the callback function
185:        DeliverInfo(requestId, fee, tx.gasprice, msg.gas, callbackGas, paramsHash, error, respData); // log the response information
