187:            callbackGas = msg.gas - 5000;
188:        }
189:        
190:        externalCallFlag = true;
191:        // <yes> <report> UNCHECKED_LL_CALLS
192:        requests[requestId].callbackAddr.call.gas(callbackGas)(requests[requestId].callbackFID, requestId, error, respData); // call the callback function in the application contract
193:        externalCallFlag = false;
194:    }
