161:    // method to determine winners and losers
162:    function play(uint ticketReveal)
163:    checkContractHealth()
164:    external
165:    {
166:        uint ticketID = uint(keccak256(abi.encodePacked(ticketReveal)));
167:        Bet storage bet = bets[ticketID];
168:        require (bet.player != address(0), "TicketID is not correct!");
169:        require (bet.amount != 0, "Ticket is already used one!");
170:        uint256 blockNumber = bet.blockNumber;
171:        if(blockNumber < block.number && blockNumber >= block.number - BET_EXPIRATION_BLOCKS)
172:        {
173:            uint256 random = uint256(keccak256(abi.encodePacked(blockhash(blockNumber),  ticketReveal)));
174:            bool maskRes = (random % 2) !=0;
175:            uint jackpotRes = random % JACKPOT_MODULO;
176:    
177:            uint tossWinAmount = bet.amount * WIN_X / 1000;
178:
179:            uint tossWin = 0;
180:            uint jackpotWin = 0;
181:            
182:            if(bet.betMask == maskRes) {
183:                tossWin = tossWinAmount;
184:            }
185:            if(jackpotRes == 0) {
186:                jackpotWin = jackpotSize;
187:                jackpotSize = 0;
188:            }
189:            if (jackpotWin > 0) {
190:                emit JackpotPayment(bet.player, ticketID, jackpotWin);
191:            }
192:            if(tossWin + jackpotWin > 0)
193:            {
194:                payout(bet.player, tossWin + jackpotWin, ticketID, maskRes, jackpotRes);
195:            }
196:            else 
197:            {
198:                loseWager(bet.player, bet.amount, ticketID, maskRes, jackpotRes);
199:            }
200:            lockedInBets -= tossWinAmount;
201:            bet.amount = 0;
202:        }
203:        else
204:        {
205:            revert();
206:        }
207:    }
